### Adding a Filter to Dict Comprehensions

Just like list comprehensions, dict comprehensions support a filtering `if` condition:

```
{KEY: VALUE   for ITEM in ITERABLE   if CONDITION}
                                        ↑
                                Only include this
                                key-value pair if
                                condition is True
```

### How It Works

```python
stock = {'apple': 50, 'banana': 0, 'cherry': 30, 'date': 0, 'elderberry': 15}

# Keep only items that are IN STOCK (qty > 0)
in_stock = {item: qty for item, qty in stock.items() if qty > 0}
print(in_stock)
# {'apple': 50, 'cherry': 30, 'elderberry': 15}
# ↑ banana and date are EXCLUDED (qty == 0)
```

### Both Filter AND Transform

```python
prices = {'coffee': 5.00, 'tea': 2.50, 'juice': 8.00, 'water': 1.00}

# Keep only expensive items (> $3) AND apply 10% discount
result = {
    item: round(price * 0.90, 2)   # Transform: 10% off
    for item, price in prices.items()
    if price > 3.00                # Filter: only expensive items
}
print(result)
# {'coffee': 4.5, 'juice': 7.2}
```

### Example 1: Filtering by Value

```python
# Filter dictionary entries based on their values

inventory = {
    'laptop':   {'stock': 5,  'price': 999},
    'mouse':    {'stock': 0,  'price': 29},
    'monitor':  {'stock': 3,  'price': 399},
    'keyboard': {'stock': 0,  'price': 79},
    'webcam':   {'stock': 8,  'price': 129},
    'headset':  {'stock': 0,  'price': 199},
}

# In-stock items only
in_stock = {name: info for name, info in inventory.items() if info['stock'] > 0}
print(list(in_stock.keys()))
# ['laptop', 'monitor', 'webcam']

# Affordable items (price < $200)
affordable = {name: info['price'] for name, info in inventory.items()
              if info['price'] < 200}
print(affordable)
# {'mouse': 29, 'keyboard': 79, 'webcam': 129, 'headset': 199}

# In-stock AND affordable
bargains = {
    name: info['price']
    for name, info in inventory.items()
    if info['stock'] > 0 and info['price'] < 200
}
print(bargains)
# {'webcam': 129}
```

### Example 2: Filtering by Key

```python
# Filter based on the KEY rather than value

config = {
    'db_host':       'localhost',
    'db_port':       5432,
    'db_name':       'myapp',
    'secret_key':    'super_secret_key_123',
    'api_key':       'sk-abc123xyz789',
    'debug':         True,
    'log_level':     'INFO',
    'cache_timeout': 300,
}

# Keep only database-related config
db_config = {k: v for k, v in config.items() if k.startswith('db_')}
print(db_config)
# {'db_host': 'localhost', 'db_port': 5432, 'db_name': 'myapp'}

# Exclude sensitive keys (for logging/display)
SENSITIVE_KEYS = {'secret_key', 'api_key'}
safe_config = {k: v for k, v in config.items() if k not in SENSITIVE_KEYS}
print(safe_config)
# {'db_host': 'localhost', 'db_port': 5432, ..., 'debug': True, ...}
# ← secret_key and api_key removed!

# Only string values (exclude ints and bools)
string_configs = {k: v for k, v in config.items() if isinstance(v, str)}
print(string_configs)
# {'db_host': 'localhost', 'db_name': 'myapp', 'secret_key': ..., 'log_level': 'INFO'}
```

### Example 3: User/Access Filtering

```python
# Permission and role-based filtering

users = {
    'alice':   {'role': 'admin',  'active': True,  'login_count': 150},
    'bob':     {'role': 'user',   'active': True,  'login_count': 45},
    'carol':   {'role': 'editor', 'active': False, 'login_count': 32},
    'dave':    {'role': 'user',   'active': True,  'login_count': 8},
    'eve':     {'role': 'admin',  'active': True,  'login_count': 200},
    'frank':   {'role': 'user',   'active': False, 'login_count': 1},
}

# Active users only
active_users = {name: info for name, info in users.items() if info['active']}
print(list(active_users.keys()))
# ['alice', 'bob', 'dave', 'eve']

# Admin users
admins = {name: info for name, info in users.items() if info['role'] == 'admin'}
print(list(admins.keys()))
# ['alice', 'eve']

# Power users (active AND more than 100 logins)
power_users = {
    name: info['login_count']
    for name, info in users.items()
    if info['active'] and info['login_count'] > 100
}
print(power_users)
# {'alice': 150, 'eve': 200}

# Dormant users (inactive OR less than 10 logins)
dormant = {
    name: info
    for name, info in users.items()
    if not info['active'] or info['login_count'] < 10
}
print(list(dormant.keys()))
# ['carol', 'dave', 'frank']
```

### Example 4: Score and Grade Filtering

```python
# Common in education/assessment systems

exam_results = {
    'Alice':   {'math': 92, 'english': 88, 'science': 95},
    'Bob':     {'math': 55, 'english': 72, 'science': 48},
    'Carol':   {'math': 78, 'english': 85, 'science': 80},
    'Dave':    {'math': 42, 'english': 50, 'science': 45},
    'Eve':     {'math': 96, 'english': 91, 'science': 98},
}

# Students who passed ALL subjects (>= 60)
def all_passed(scores: dict) -> bool:
    return all(s >= 60 for s in scores.values())

passed_all = {name: scores for name, scores in exam_results.items()
              if all_passed(scores)}
print(list(passed_all.keys()))
# ['Alice', 'Carol', 'Eve']

# Students with average >= 80 (high performers)
high_performers = {
    name: round(sum(scores.values()) / len(scores), 1)
    for name, scores in exam_results.items()
    if sum(scores.values()) / len(scores) >= 80
}
print(high_performers)
# {'Alice': 91.7, 'Carol': 81.0, 'Eve': 95.0}

# Failed students (at least one score < 60)
failed = {
    name: [sub for sub, score in scores.items() if score < 60]
    for name, scores in exam_results.items()
    if any(s < 60 for s in scores.values())
}
print(failed)
# {'Bob': ['math', 'science'], 'Dave': ['math', 'english', 'science']}
```

### Example 5: Real-World API Response Filtering

```python
# Filter and transform API response data

api_products = {
    'P001': {'name': 'Laptop Pro',   'price': 1299, 'rating': 4.8, 'reviews': 324,  'available': True},
    'P002': {'name': 'Basic Mouse',  'price': 19,   'rating': 3.2, 'reviews': 45,   'available': True},
    'P003': {'name': 'Monitor 4K',   'price': 599,  'rating': 4.6, 'reviews': 189,  'available': False},
    'P004': {'name': 'Keyboard Pro', 'price': 149,  'rating': 4.9, 'reviews': 512,  'available': True},
    'P005': {'name': 'Webcam HD',    'price': 89,   'rating': 4.1, 'reviews': 8,    'available': True},
    'P006': {'name': 'USB Hub',      'price': 39,   'rating': 3.8, 'reviews': 156,  'available': True},
}

# Highly rated available products (rating >= 4.5 and available)
top_products = {
    pid: {'name': p['name'], 'price': p['price'], 'rating': p['rating']}
    for pid, p in api_products.items()
    if p['available'] and p['rating'] >= 4.5
}
print(top_products)
# {'P001': {...}, 'P004': {...}}

# Products with enough reviews to trust the rating (>= 100 reviews)
trusted = {
    pid: p['name']
    for pid, p in api_products.items()
    if p['reviews'] >= 100
}
print(trusted)
# {'P001': 'Laptop Pro', 'P003': 'Monitor 4K', 'P004': 'Keyboard Pro', 'P006': 'USB Hub'}

# Budget recommendations (available, < $100, rating >= 4.0)
budget_picks = {
    pid: f"{p['name']} (${p['price']}) ⭐{p['rating']}"
    for pid, p in api_products.items()
    if p['available'] and p['price'] < 100 and p['rating'] >= 4.0
}
print(budget_picks)
# {'P005': 'Webcam HD ($89) ⭐4.1', 'P006': 'USB Hub ($39) ⭐3.8'}
# Wait — P006 rating is 3.8 < 4.0, so:
# {'P005': 'Webcam HD ($89) ⭐4.1'}
```
